const attrs = (msg.strip_entity && msg.strip_entity.attributes) || {};
const rawBrightness = attrs.brightness || 0;
const currentPct = Math.round(rawBrightness / 255 * 100);
let newPct = currentPct - 10;
if (newPct < 10) {
    newPct = 10;
}
msg.payload = newPct;
const trackedEffect = flow.get('currentEffect');
msg.effectWasActive = !!trackedEffect;
msg.previousEffect = trackedEffect;
return msg;

function randByte() {
    return Math.floor(Math.random() * 256);
}
msg.payload = [randByte(), randByte(), randByte()];
return msg;

// Kelvin scale: lower = warmer, higher = cooler
// adjust these 3 values to match your strip's actual min/max kelvin if different
 const steps = [6500, 3250, 2000]; // cool, 50/50, warm
 const labels = ['cool', '50/50', 'warm'];

let idx = flow.get('whiteCycleIndex');
if (typeof idx !== 'number' || idx < 0 || idx > 2) {
    idx = 0;
} else {
    idx = (idx + 1) % 3;
}
flow.set('whiteCycleIndex', idx);

msg.payload = steps[idx];
msg.whiteStepLabel = labels[idx];
return msg;
